"""Transformation `lab_control_check`: custom steps generated by package-factory 0.2.0; review before approving.

Plan (approved by @claude-demo):
  1. check_control_files [custom] Verify each delivery folder has one control file with a matching file count
  2. drop_control_files [select] Remove the control files
  3. move_to_data [move] Move files to data/<delivery folder>/<file name>, dropping sub-folders
  4. compute_checksums [checksum] Compute md5 and sha256 for every file
  5. write_manifest [manifest] Write manifest.csv with path, size, md5, sha256

Each custom function: def <step_id>(pkg, params, ctx): — only function bodies may be edited
(then `pkf test transformation lab_control_check` and approve again).
Plan digest: eb3b348e625bcd53e3e45f29555f44b3517e8fdc5da693785d6ad0f57aaba1aa
"""
from __future__ import annotations


def check_control_files(pkg, params, ctx):
    import re
    files = pkg.files()
    if not files:
        pkg.fail('empty package')
        return
    pattern = re.compile(r'CONTROL_(\d+)\.txt')
    groups = {}
    for path in files:
        parts = path.split('/')
        if len(parts) < 2:
            pkg.fail('file outside a delivery folder')
            return
        groups.setdefault(parts[0], []).append(parts[1:])
    for folder in sorted(groups):
        rest_list = groups[folder]
        controls = []
        for rest in rest_list:
            m = pattern.fullmatch(rest[-1])
            if m:
                controls.append(m)
        if len(controls) != 1:
            pkg.fail('delivery folder %s must have exactly one control file, found %d' % (folder, len(controls)))
            return
        n = int(controls[0].group(1))
        others = len(rest_list) - 1
        if n != others:
            pkg.fail('delivery folder %s control count mismatch: expected %d, actual %d' % (folder, n, others))
            return


CUSTOM = {"check_control_files": check_control_files}
